const categories=[
{title:'专业服务：用小范围服务建立第一轮信任',text:'适合需要沟通才能确定方案的咨询、设计或运营服务。文章以预约或诊断作为入口，再讨论更完整的服务。关键在于体验与正式服务的边界清楚。',path:['预约 / 诊断','了解需求','正式方案']},
{title:'数字资料：入口轻，交付需要具体',text:'模板、教程和资料包是文章列举的轻交付品类。阅读时重点看资料是否对应目标人群的真实问题，而不是只把“价格低”当作吸引力。',path:['明确主题','资料交付','后续答疑']},
{title:'教学与陪跑：先体验，再确认适配',text:'作者把试听、体验和后续教学串成一条路径。前端说明教学对象与学习内容，后续沟通确认学习目标、服务形式与正式费用。',path:['试听 / 体验','目标沟通','持续教学']},
{title:'入门体验品：入口与后续产品必须相关',text:'原文列举样品、资料包和体验装。低价产品承担初次体验，后续服务承担更深需求；两者面对同一类客户，链路才有意义。',path:['入门产品','实际体验','后续需求']},
{title:'同城服务：先把地区说清楚',text:'家教、保洁和宠物照护等服务受地域约束。作者强调城市与服务范围的表达，再通过本地交付积累信任和转介绍。',path:['地区搜索','沟通范围','本地交付']},
{title:'高客单前端：用相关小需求连接专业服务',text:'文章建议从相关资料或小范围咨询切入，而不是只竞争最宽泛的大词。重点是来访者的需求是否与后续专业服务匹配。',path:['相关小需求','专业沟通','完整服务']}
];
function showCategory(i){const c=categories[i];document.getElementById('catTitle').textContent=c.title;document.getElementById('catText').textContent=c.text;document.getElementById('catPath').replaceChildren(...c.path.flatMap((t,j)=>{const s=document.createElement('span');s.textContent=t;if(!j)return[s];const a=document.createElement('b');a.innerHTML='<svg class="icon" aria-hidden="true"><use href="#i-arrow"/></svg>';return[a,s]}));document.querySelectorAll('[data-cat]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.cat)===i)))}
document.querySelectorAll('[data-cat]').forEach(b=>b.addEventListener('click',()=>showCategory(Number(b.dataset.cat))));showCategory(0);
const days=[['熟悉平台','浏览推荐与商品详情，先了解常见商品如何呈现。'],['加深观察','多看搜索结果和卖家主页，熟悉平台的基础功能。'],['轻量互动','围绕真实兴趣收藏或咨询，理解卖家怎样回应需求。'],['聚焦品类','集中观察计划提供的服务，认识同类商品与目标人群。'],['真实购买','原文安排一次小额购买，用实际交易理解购买流程。'],['完成交易','在实际收货后完成确认与评价，理解完整的交易体验。'],['发布前检查','查看账号状态和服务资料，准备进入商品测试阶段。']];
function showDay(i){document.getElementById('dayIndex').textContent=String(i+1).padStart(2,'0');document.getElementById('dayTitle').textContent=days[i][0];document.getElementById('dayText').textContent=days[i][1];document.querySelectorAll('[data-day]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.day)===i)))}
days.forEach((d,i)=>{const b=document.createElement('button');b.dataset.day=i;b.setAttribute('aria-label',`第 ${i+1} 天：${d[0]}`);b.innerHTML=`DAY<strong>${i+1}</strong>`;b.addEventListener('click',()=>showDay(i));document.getElementById('days').append(b)});showDay(0);
const diagnostics=[['检查入口：关键词与类目','先判断商品是否匹配用户搜索，再观察账号和发布条件。不急着同时改主图、价格和正文。'],['检查第一眼：主图与标题','用户已看到但没有点击，优先让商品主题、适用对象和价值更直观。'],['检查详情：内容与交付表达','点击已经发生，下一步检查服务范围、交付结果、价格和信任依据是否清楚。'],['检查匹配：人群与服务范围','对照实际咨询内容，看关键词是否吸引了不匹配的需求，再有针对性地调整。'],['保留有效结构，逐步扩大','先确认咨询质量与真实交付情况。保留已经奏效的表达，观察一段时间后再复制或放大。']];
function showDiagnostic(){const d=diagnostics[Number(document.getElementById('signal').value||'0')];document.getElementById('diagTitle').textContent=d[0];document.getElementById('diagText').textContent=d[1]}document.getElementById('signal').addEventListener('change',showDiagnostic);showDiagnostic();
document.getElementById('theme').addEventListener('click',()=>{const dark=document.body.classList.toggle('dark');document.querySelector('#theme span').textContent=dark?'日间阅读':'夜间阅读';document.querySelector('#theme use').setAttribute('href',dark?'#i-sun':'#i-moon');document.getElementById('theme').setAttribute('aria-label',dark?'切换浅色模式':'切换深色模式')});let large=false;document.getElementById('font').addEventListener('click',()=>{large=!large;document.documentElement.style.setProperty('--body-size',large?'20px':'17px');document.querySelector('#font span').textContent=large?'标准字号':'大字阅读';document.getElementById('font').setAttribute('aria-label',large?'恢复正文字号':'增大正文字号')});
const sections=[...document.querySelectorAll('main section[id]')];const navLinks=[...document.querySelectorAll('.layout aside nav a')];function updateReading(){const total=document.documentElement.scrollHeight-innerHeight;document.getElementById('progress').style.width=`${total>0?Math.min(100,scrollY/total*100):0}%`;let current=sections[0].id;for(const s of sections){if(s.getBoundingClientRect().top<190)current=s.id}navLinks.forEach(a=>{const active=a.hash==='#'+current;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current')})}addEventListener('scroll',updateReading,{passive:true});addEventListener('resize',updateReading);updateReading();
